mapper.insert:
INSERT INTO business_trip_request (
    employee_id, trip_type, destination, start_datetime, end_datetime, reason, approval_status
) VALUES (
             #{employeeId}, #{tripType}, #{destination}, #{startDatetime}, #{endDatetime}, #{reason}, #{approvalStatus}
         )

mapper.select:
SELECT COUNT(*)
FROM business_trip_request
WHERE employee_id = #{employeeId}

SELECT COUNT(*)
FROM business_trip_request
WHERE employee_id = #{employeeId}
  AND approval_status IN ('PENDING', 'APPROVED')
  AND start_datetime <= #{endDate}
  AND end_datetime >= #{startDate}

mapper.update:
UPDATE business_trip_request
SET approval_status = #{approvalStatus},
    reject_reason = #{rejectReason}
WHERE trip_id = #{tripId}
  AND approval_status = 'PENDING'

mapper.select:
SELECT trip_id as tripId, employee_id as employeeId, trip_type as tripType, destination as destination, start_datetime as startDatetime, end_datetime as endDatetime, reason as reason, approval_status as approvalStatus, reject_reason as rejectReason FROM business_trip_request
approval_status = #{approvalStatus}
ORDER BY start_datetime DESC, trip_id DESC LIMIT #{limit} OFFSET #{offset}
